SELECT 
FROM post_comment c
WHERE c.post_id = #{postId}
  AND c.root_id = '0'
  AND (c.state = 'NORMAL'

          OR (c.state = 'PENDING_REVIEW' AND c.user_id = #{viewerId})
          OR (c.state = 'REJECTED' AND c.user_id = #{viewerId})

  )
ORDER BY c.create_time, c.comment_id
LIMIT #{offset}, #{limit}

SELECT comment_id
FROM post_comment_feed_index
WHERE post_id = #{postId}
ORDER BY like_count DESC, create_time, comment_id
LIMIT #{offset}, #{limit}

SELECT 
FROM post_comment c
WHERE c.root_id = #{rootId}
  AND (c.state = 'NORMAL'

          OR (c.state IN ('PENDING_REVIEW', 'REJECTED') AND c.user_id = #{viewerId})

  )
ORDER BY c.create_time, c.comment_id
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM post_comment
WHERE root_id = #{rootId}
  AND (state = 'NORMAL'

          OR (state IN ('PENDING_REVIEW', 'REJECTED') AND user_id = #{viewerId})

  )

